1|// RTK port: compress tool_result content in LLM request bodies
2|// Applied in chatCore: on the source-format body for Cursor (its translator folds
3|// tool results into user XML), post-translate for every other provider.
4|import { RAW_CAP, MIN_COMPRESS_SIZE } from "./constants.js";
5|import { autoDetectFilter } from "./autodetect.js";
6|import { safeApply } from "./applyFilter.js";
7|
8|let _rtkEnabled = false;
9|export function setRtkEnabled(v) { _rtkEnabled = !!v; }
10|export function isRtkEnabled() { return _rtkEnabled; }
11|
12|// The per-message sync pass is what stalls the event loop on ~700 KB agent
13|// sessions, so skip compression entirely above this size. Override per deployment.
14|export const RTK_MAX_BODY_BYTES = parseInt(process.env.NINEROUTER_RTK_MAX_BYTES || "", 10) || 512 * 1024;
15|
16|// Compress tool_result content in-place. Returns stats or null if disabled/failed.
17|export function compressMessages(body, enabled, bytes) {
18|  if (enabled === undefined) enabled = _rtkEnabled;
19|  if (!enabled) return null;
20|  if (!body) return null;
21|  const bodyBytes = Number.isFinite(bytes) ? bytes : estimateBodyBytes(body);
22|  if (bodyBytes > RTK_MAX_BODY_BYTES) return null;
23|
24|  // Kiro format: conversationState.history + conversationState.currentMessage
25|  if (body.conversationState) {
26|    return compressKiroFormat(body, enabled);
27|  }
28|
29|  // Support both OpenAI/Claude "messages" and OpenAI Responses "input"
30|  const items = Array.isArray(body.messages) ? body.messages
31|    : Array.isArray(body.input) ? body.input
32|    : null;
33|  if (!items) return null;
34|
35|  const stats = { bytesBefore: 0, bytesAfter: 0, hits: [] };
36|  try {
37|    for (let i = 0; i < items.length; i++) {
38|      const msg = items[i];
39|      if (!msg) continue;
40|
41|      // Shape 4: OpenAI Responses — top-level { type:"function_call_output", output: string | [{type:"input_text", text}] }
42|      if (msg.type === "function_call_output") {
43|        if (typeof msg.output === "string") {
44|          msg.output = compressText(msg.output, stats, "openai-responses-string");
45|        } else if (Array.isArray(msg.output)) {
46|          for (let k = 0; k < msg.output.length; k++) {
47|            const part = msg.output[k];
48|            if (part && part.type === "input_text" && typeof part.text === "string") {
49|              part.text = compressText(part.text, stats, "openai-responses-array");
50|            }
51|          }
52|        }
53|        continue;
54|      }
55|
56|      // Shape 1: OpenAI tool message — { role:"tool", content: "string" }
57|      if (msg.role === "tool" && typeof msg.content === "string") {
58|        msg.content = compressText(msg.content, stats, "openai-tool");
59|        continue;
60|      }
61|
62|      if (!Array.isArray(msg.content)) continue;
63|
64|      // Shape 1b: OpenAI tool message — { role:"tool", content:[{type:"text", text:"..."}] }
65|      if (msg.role === "tool") {
66|        for (let k = 0; k < msg.content.length; k++) {
67|          const part = msg.content[k];
68|          if (part && part.type === "text" && typeof part.text === "string") {
69|            part.text = compressText(part.text, stats, "openai-tool-array");
70|          }
71|        }
72|        continue;
73|      }
