  opencode: FORMATS.OPENAI,
  nvidia: FORMATS.OPENAI,
  openrouter: FORMATS.OPENAI,
  "glm-cn": FORMATS.OPENAI,
  mistral: FORMATS.OPENAI,
  xai: FORMATS.OPENAI,
  cohere: FORMATS.OPENAI,
  together: FORMATS.OPENAI,
